INSERT INTO items_official (tipo, aeropuerto, pais, item_en, item_es, precio, descripcion_en, descripcion_es, notas) VALUES ('IMPO', 'UIO', 'Ecuador', 'Customs clearance', 'Liberación de aduana', '1 pet: USD 890 / 2 pets: USD 940 / 3 pets: USD 990', 'Includes our charges, our customs agent''s charges and Agrocalidad''s fees. Does not include the Ecuadorian Customs'' import tax for the animal''s import.', 'Proceso de aprobación de la importación de animales vivos por parte del Servicio Nacional de Aduana del Ecuador (SENAE). Cotizado para arribos dentro del horario laboral de 8 am a 8 pm.', 'Documents and information must be received 48 hs before pets arrival.');
INSERT INTO items_official (tipo, aeropuerto, pais, item_en, item_es, precio, descripcion_en, descripcion_es, notas) VALUES ('IMPO', 'UIO', 'Ecuador', 'Import taxes in Ecuador', 'Impuestos de importación', '43% of airfreight and pet value in AWB', 'Ecuador taxes the import of pet animals. Total cost is approximately 43% of CIF value.', 'Impuestos a cobrar de acuerdo al valor declarado en la guía aérea (43%).', NULL);
INSERT INTO items_official (tipo, aeropuerto, pais, item_en, item_es, precio, descripcion_en, descripcion_es, notas) VALUES ('IMPO', 'UIO', 'Ecuador', 'Import Formalities', 'Trámites de importación', 'USD 370', 'Import tariff rights and service fees.', 'Derechos arancelarios y tasas por servicios de importación.', NULL);
INSERT INTO items_official (tipo, aeropuerto, pais, item_en, item_es, precio, descripcion_en, descripcion_es, notas) VALUES ('IMPO', 'UIO', 'Ecuador', 'Warehouse', 'Acceso a la bodega', '1 pet: USD 90 / 2 pets: USD 120 / 3 pets: USD 150', 'Pet(s) will be placed in airport''s warehouse during custom clearance.', 'Tarifa aplicada por acceso a la bodega. La mascota permanecerá en la bodega durante el proceso de liberación de aduana.', NULL);
INSERT INTO items_official (tipo, aeropuerto, pais, item_en, item_es, precio, descripcion_en, descripcion_es, notas) VALUES ('IMPO', 'UIO', 'Ecuador', 'Health Authorities fees (Agrocalidad)', 'Agrocalidad', '1 pet: USD 190 / 2 pets: USD 210 / 3 pets: USD 230', 'Fees charged by Health Authorities at the airport.', 'Inspección sanitaria por parte de un profesional veterinario de Agrocalidad al ingreso al país.', NULL);
INSERT INTO items_official (tipo, aeropuerto, pais, item_en, item_es, precio, descripcion_en, descripcion_es, notas) VALUES ('IMPO', 'UIO', 'Ecuador', 'Home delivery', 'Entrega en el domicilio', '1 pet: USD 250 / 2 pets: USD 280 / 3 pets: USD 310', 'Pick up from UIO airport and delivery to owner''s residence in Quito metro area.', 'Entrega de la mascota en el domicilio del cliente dentro del área metropolitana de Quito.', NULL);
INSERT INTO items_official (tipo, aeropuerto, pais, item_en, item_es, precio, descripcion_en, descripcion_es, notas) VALUES ('IMPO', 'MEX', 'México', 'Customs Clearance MEX airport', 'Liberación de Aduana en Aeropuerto de MEX', '1 pet: USD 1,200 / 2 pets: USD 1,430 / 3 pets: USD 1,680 / 4 pets: USD 1,830 (Puppy 1 pet: USD 1,600)', 'Includes our charges, our customs agent''s charges and health authorities fees (SENASICA).', 'Incluye nuestros costos, los costos de nuestro agente y los costos de SENASICA. No incluye los costos de aduana de México por importación de animales.', 'Surcharge applies if clearance is outside normal working days and hours.');
INSERT INTO items_official (tipo, aeropuerto, pais, item_en, item_es, precio, descripcion_en, descripcion_es, notas) VALUES ('IMPO', 'MEX', 'México', 'Import taxes Mexico', 'Impuestos de Importación México', '20% of the CIF value', 'Mexico taxes the import of pets. Total cost is approximately 20% over CIF value + commercial value of the pet.', 'México grava la importación de mascotas. El costo total es aproximadamente un 20% superior al valor CIF más el valor comercial de la mascota.', NULL);
INSERT INTO items_official (tipo, aeropuerto, pais, item_en, item_es, precio, descripcion_en, descripcion_es, notas) VALUES ('IMPO', 'MEX', 'México', 'IGI import tax', 'Impuesto IGI', '16% applicable; exempt only with valid certificate from the U.S., Canada, U.K., or Europe', '16% applicable; exempt only with valid certificate from the U.S., Canada, U.K., or Europe.', '16% aplicable; exento solo con certificado válido de EE. UU., Canadá, Reino Unido o Europa.', NULL);
INSERT INTO items_official (tipo, aeropuerto, pais, item_en, item_es, precio, descripcion_en, descripcion_es, notas) VALUES ('IMPO', 'MEX', 'México', 'Airline fee to transfer to Warehouse', 'Impuesto a la aerolínea — transferencia a bodega', '1 pet: USD 180 / 2 pets: USD 230 / 3 pets: USD 280 / 4 pets: USD 320', 'Airline fee to transfer to the warehouse at the airport so pets can be assisted.', 'Impuesto a la aerolínea para la transferencia a la bodega en el aeropuerto para asistir a las mascotas.', NULL);
INSERT INTO items_official (tipo, aeropuerto, pais, item_en, item_es, precio, descripcion_en, descripcion_es, notas) VALUES ('IMPO', 'MEX', 'México', 'Warehouse Access', 'Acceso a la bodega', '1 pet: USD 120 / 2 pets: USD 140 / 3 pets: USD 160 / 4 pets: USD 180', 'The pet will be in the warehouse until the customs clearing process is completed.', 'La mascota permanecerá en la bodega hasta que se complete la liberación de aduana.', NULL);
INSERT INTO items_official (tipo, aeropuerto, pais, item_en, item_es, precio, descripcion_en, descripcion_es, notas) VALUES ('IMPO', 'MEX', 'México', 'Home delivery in Metro Mexico City', 'Entrega en Domicilio en Ciudad de México', '1 pet: USD 280 / 2 pets: USD 300 / 3 pets: USD 350 / 4 pets: USD 400', 'Transport from MEX airport to client''s residence in metro Mexico City.', 'Nuestro personal entregará la(s) mascota(s) en el domicilio del cliente en Ciudad de México.', NULL);
