INSERT INTO items_official (tipo, aeropuerto, pais, item_en, item_es, precio, descripcion_en, descripcion_es, notas) VALUES ('IMPO', 'LIM', 'Perú', 'Import taxes Peru', 'Impuestos de importación', '35% of CIF value (applies from the 2nd pet if not exempted)', 'Peru taxes the import of pet animals. Total cost is approximately 35% over CIF value, applies on the 2nd pet.', 'Impuestos a cobrar de acuerdo al valor declarado en la guía aérea (35%). Se aplica a partir de la 2ª mascota si no está exenta.', '35% of CIF value will apply if not exempted on the 2nd pet.');
