INSERT INTO items_official (tipo, aeropuerto, pais, item_en, item_es, precio, descripcion_en, descripcion_es, notas) VALUES ('IMPO', 'CUN', 'México', 'Home delivery (zone-based)', 'Entrega en domicilio (por zona)', 'Metro Cancún: 1 pet USD 200 / 2 pets USD 200 / 3 pets USD 250 | Puerto Morelos: 1 pet USD 300 / 2 pets USD 250 / 3 pets USD 300 | Playa del Carmen: USD 400 | Tulum: USD 500 | Cozumel: 1-2 pets USD 500 / 3 pets USD 550 + ferry | Isla Mujeres: USD 500 + ferry', 'Transport from CUN airport to client''s residence. Price varies by delivery zone.', 'Traslado desde el aeropuerto CUN al domicilio del cliente. El precio varía según la zona de entrega.', 'Cozumel and Isla Mujeres: additional ferry fees apply.');
