CREATE TABLE IF NOT EXISTS items_official (
  id             SERIAL PRIMARY KEY,
  tipo           VARCHAR(20)  NOT NULL,
  aeropuerto     VARCHAR(10),
  pais           VARCHAR(100) NOT NULL,
  item_en        TEXT         NOT NULL,
  item_es        TEXT         NOT NULL,
  precio         TEXT,
  descripcion_en TEXT,
  descripcion_es TEXT,
  notas          TEXT
);

